<?php
require __DIR__.'/bootstrap.php';$items=[];$subtotal=0;foreach($_SESSION['cart']??[] as $id=>$qty){$q=$pdo->prepare('SELECT * FROM products WHERE id=? AND active=1');$q->execute([(int)$id]);$p=$q->fetch();if(!$p||(int)$p['stock']<(int)$qty){flash('A product in your bag is unavailable or has insufficient stock.','error');redirect('cart.php');}$price=(float)($p['sale_price']?:$p['price']);$subtotal+=$price*(int)$qty;$items[]=['p'=>$p,'qty'=>(int)$qty,'price'=>$price];}if(!$items)redirect('cart.php');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$wa=trim($_POST['whatsapp']??'');$email=trim($_POST['email']??'');$province=trim($_POST['province']??'');$city=trim($_POST['city']??'');$district=trim($_POST['district']??'');$address=trim($_POST['address']??'');$postal=trim($_POST['postal_code']??'');$notes=trim($_POST['notes']??'');if(!$name||!$wa||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$province||!$city||!$address)$error='Please complete all required fields with a valid email.';else{try{$pdo->beginTransaction();$grand=$subtotal+(float)setting($pdo,'shipping_fee','0');$number='K6-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$q=$pdo->prepare("INSERT INTO orders(order_number,customer_name,whatsapp,email,province,city,district,address,postal_code,notes,subtotal,shipping_fee,total,status,payment_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,'Pending','Awaiting Payment')");$q->execute([$number,$name,$wa,$email,$province,$city,$district,$address,$postal,$notes,$subtotal,(float)setting($pdo,'shipping_fee','0'),$grand]);$oid=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,sku,unit_price,quantity,line_total) VALUES(?,?,?,?,?,?,?)');$stock=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=? AND active=1 AND stock>=?');foreach($items as $it){$p=$it['p'];$stock->execute([$it['qty'],$p['id'],$it['qty']]);if($stock->rowCount()!==1)throw new RuntimeException('Stock changed while placing your order. Please try again.');$ins->execute([$oid,$p['id'],$p['name'],$p['sku'],$it['price'],$it['qty'],$it['price']*$it['qty']]);}$pdo->commit();unset($_SESSION['cart']);$_SESSION['last_order']=$number;redirect('order_success.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Checkout error: '.$e->getMessage());$error=$e instanceof RuntimeException?$e->getMessage():'Could not place your order. Please try again.';}}}
site_header($pdo,'Checkout'); ?>
<section class="page-intro"><span class="eyebrow">ALMOST YOURS</span><h1>Checkout</h1></section><section class="section checkout-layout"><form method="post" class="checkout-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><?php if($error): ?><div class="notice error"><?=e($error)?></div><?php endif; ?><h2>Delivery details</h2><label>Full name *<input required name="name" value="<?=e($_POST['name']??'')?>"></label><label>WhatsApp number *<input required name="whatsapp" type="tel" value="<?=e($_POST['whatsapp']??'')?>"></label><label>Email *<input required type="email" name="email" value="<?=e($_POST['email']??'')?>"></label><label>Province *<input required name="province" value="<?=e($_POST['province']??'')?>"></label><label>City *<input required name="city" value="<?=e($_POST['city']??'')?>"></label><label>District<input name="district" value="<?=e($_POST['district']??'')?>"></label><label>Full address *<textarea required name="address"><?=e($_POST['address']??'')?></textarea></label><label>Postal code<input name="postal_code" value="<?=e($_POST['postal_code']??'')?>"></label><label>Order notes<textarea name="notes"><?=e($_POST['notes']??'')?></textarea></label><button class="button" type="submit">PLACE ORDER</button><p class="muted">Order will be created as awaiting payment. No payment gateway is connected.</p></form><aside class="summary"><h2>Your order</h2><?php foreach($items as $it): ?><p><?=e($it['p']['name'])?> × <?=$it['qty']?> <b><?=money($it['price']*$it['qty'])?></b></p><?php endforeach; ?><hr><p>Subtotal <b><?=money($subtotal)?></b></p><p>Shipping <b><?=money((float)setting($pdo,'shipping_fee','0'))?></b></p><p class="total">Total <b><?=money($subtotal+(float)setting($pdo,'shipping_fee','0'))?></b></p></aside></section><?php site_footer($pdo); ?>
